class MultiInit {
    static int staticValue = 1;
    static {
        staticValue *= 10; // staticValue = 10, TYLKO RAZ
    }
    int instanceValue = 1;
    {
        instanceValue += 100; // instanceValue = 101, za każdym razem
    }
    MultiInit() {
        instanceValue *= 2; // instanceValue = 202, za każdym razem
    }
}

public static void main(String[] args) {
    MultiInit m1 = new MultiInit();
    MultiInit m2 = new MultiInit();
    System.out.println("staticValue: " + MultiInit.staticValue); // 10
    System.out.println("m1.instanceValue: " + m1.instanceValue); // 202
    System.out.println("m2.instanceValue: " + m2.instanceValue); // 202 (identyczne, bo każdy obiekt liczy od nowa)
}

