class Matrix {
    int[][] data;
    Matrix(int rows, int cols) {
        data = new int[rows][cols];
    }
    Matrix(int[][] source) {
        data = new int[source.length][source[0].length];
        for (int i = 0; i < source.length; i++) {
            data[i] = java.util.Arrays.copyOf(source[i], source[i].length);
        }
    }
    void print() {
        for (int[] row : data) System.out.println(java.util.Arrays.toString(row));
    }
}

