class Connection {
    static Connection[] pool = { new Connection(1), new Connection(2), new Connection(3) };
    int id;
    boolean inUse = false;
    private Connection(int id) { this.id = id; }
    static Connection acquire() {
        for (Connection c : pool) {
            if (!c.inUse) { c.inUse = true; return c; }
        }
        return null;
    }
    static void release(Connection c) { c.inUse = false; }
}

public static void main(String[] args) {
    Connection c1 = Connection.acquire();
    Connection c2 = Connection.acquire();
    Connection c3 = Connection.acquire();
    Connection c4 = Connection.acquire();
    System.out.println("c1=" + c1.id + ", c4=" + c4);
    Connection.release(c1);
    Connection c5 = Connection.acquire();
    System.out.println("c5 (po zwolnieniu)=" + c5.id);
}

