abstract class Shape {
    String color;
    Shape(String color) { this.color = color; }
    abstract double area();
}

class Circle extends Shape {
    double radius;
    Circle(String color, double radius) { super(color); this.radius = radius; }
    double area() { return Math.PI * radius * radius; }
}

class Square extends Shape {
    double side;
    Square(String color, double side) { super(color); this.side = side; }
    double area() { return side * side; }
}

public static void main(String[] args) {
    Shape circle = new Circle("red", 3);
    Shape square = new Square("blue", 4);
    System.out.println(circle.color + ": " + circle.area());
    System.out.println(square.color + ": " + square.area());
}

class ImmutableList {
    private final String[] items;
    ImmutableList(String[] items) { this.items = java.util.Arrays.copyOf(items, items.length); }
    ImmutableList with(String newItem) {
        String[] newItems = java.util.Arrays.copyOf(items, items.length + 1);
        newItems[items.length] = newItem;
        return new ImmutableList(newItems);
    }
    String get(int index) { return items[index]; }
    int size() { return items.length; }
}

public static void main(String[] args) {
    ImmutableList list1 = new ImmutableList(new String[]{"a", "b"});
    ImmutableList list2 = list1.with("c");
    System.out.println("list1 size: " + list1.size());
    System.out.println("list2 size: " + list2.size());
}

class Temperature {
    private final double kelvin;
    private Temperature(double kelvin) { this.kelvin = kelvin; }
    static Temperature fromCelsius(double c) { return new Temperature(c + 273.15); }
    static Temperature fromFahrenheit(double f) { return new Temperature((f - 32) * 5 / 9 + 273.15); }
    double getCelsius() { return kelvin - 273.15; }
    double getFahrenheit() { return (kelvin - 273.15) * 9 / 5 + 32; }
    double getKelvin() { return kelvin; }
}

public static void main(String[] args) {
    Temperature t1 = Temperature.fromCelsius(20);
    System.out.println(t1.getCelsius() + "C, " + t1.getFahrenheit() + "F, " + t1.getKelvin() + "K");
}

class TreeNode {
    int value;
    TreeNode left, right;
    TreeNode(int value) { this.value = value; }
    void setLeft(TreeNode left) { this.left = left; }
    void setRight(TreeNode right) { this.right = right; }
    int sum() {
        int total = value;
        if (left != null) total += left.sum();
        if (right != null) total += right.sum();
        return total;
    }
}

public static void main(String[] args) {
    TreeNode root = new TreeNode(10);
    root.setLeft(new TreeNode(5));
    root.setRight(new TreeNode(15));
    System.out.println("Suma: " + root.sum());
}

class Order {
    final String customerId, deliveryAddress, paymentMethod;
    final java.util.List<String> items;
    private Order(Builder b) {
        this.customerId = b.customerId; this.items = b.items;
        this.deliveryAddress = b.deliveryAddress; this.paymentMethod = b.paymentMethod;
    }
    static class Builder {
        String customerId, deliveryAddress, paymentMethod;
        java.util.List<String> items = new java.util.ArrayList<>();
        Builder customer(String id) { this.customerId = id; return this; }
        Builder addItem(String item) { items.add(item); return this; }
        Builder deliver(String address) { this.deliveryAddress = address; return this; }
        Builder pay(String method) { this.paymentMethod = method; return this; }
        Order build() { return new Order(this); }
    }
}

public static void main(String[] args) {
    Order order = new Order.Builder()
        .customer("CUST-1").addItem("Laptop").addItem("Mysz")
        .deliver("ul. Dluga 5").pay("card").build();
    System.out.println(order.customerId + ": " + order.items + " -> " + order.deliveryAddress + ", " + order.paymentMethod);
}
